import{_ as s,c as i,o as a,ag as t}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Self-Hosting Jitsi","description":"","frontmatter":{"title":"Self-Hosting Jitsi"},"headers":[],"relativePath":"general/self-hosting-jitsi.md","filePath":"general/self-hosting-jitsi.md","lastUpdated":null}'),n={name:"general/self-hosting-jitsi.md"};function o(r,e,l,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="self-hosting-jitsi" tabindex="-1">Self-Hosting Jitsi <a class="header-anchor" href="#self-hosting-jitsi" aria-label="Permalink to &quot;Self-Hosting Jitsi&quot;">​</a></h1><h2 id="self-hosting-jitsi-guide" tabindex="-1">Self-Hosting Jitsi Guide <a class="header-anchor" href="#self-hosting-jitsi-guide" aria-label="Permalink to &quot;Self-Hosting Jitsi Guide&quot;">​</a></h2><p>This guide provides instructions for self-hosting Jitsi as part of a Matrix Docker setup, covering the main configuration variables, troubleshooting known issues, and managing the service.</p><h3 id="configuration-variables-vars" tabindex="-1">Configuration Variables (VARS) <a class="header-anchor" href="#configuration-variables-vars" aria-label="Permalink to &quot;Configuration Variables (VARS)&quot;">​</a></h3><p>Add the following configuration options to your <code>vars.yml</code> file to enable and configure Jitsi:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>matrix_jitsi_enabled: true</span></span>
<span class="line"><span>matrix_jitsi_enable_guests: true</span></span>
<span class="line"><span>matrix_jitsi_enable_lobby: false</span></span>
<span class="line"><span>jitsi_prosody_auth_matrix_uvs_sync_power_levels: false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>These variables control Jitsi&#39;s behavior within your Matrix instance:</p><ul><li><p><code>matrix_jitsi_enabled</code>: Enables Jitsi for video conferencing.</p></li><li><p><code>matrix_jitsi_enable_guests</code>: Allows guests to join without an account.</p></li><li><p><code>matrix_jitsi_enable_lobby</code>: Enables or disables the Jitsi lobby feature for waiting rooms.</p></li><li><p><code>jitsi_prosody_auth_matrix_uvs_sync_power_levels</code>: Syncs Jitsi moderation with Matrix power levels.</p></li></ul><h3 id="managing-jitsi" tabindex="-1">Managing Jitsi <a class="header-anchor" href="#managing-jitsi" aria-label="Permalink to &quot;Managing Jitsi&quot;">​</a></h3><p>To manage the Jitsi service (start, stop, restart), use the following commands:</p><h3 id="stopping-jitsi" tabindex="-1">Stopping Jitsi <a class="header-anchor" href="#stopping-jitsi" aria-label="Permalink to &quot;Stopping Jitsi&quot;">​</a></h3><p>To stop only the Jitsi service, run:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ansible-playbook -i inventory/hosts setup.yml --tags=stop-group --extra-vars=group=jitsi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="restarting-jitsi" tabindex="-1">Restarting Jitsi <a class="header-anchor" href="#restarting-jitsi" aria-label="Permalink to &quot;Restarting Jitsi&quot;">​</a></h3><p>To stop and then start the Jitsi service, run:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ansible-playbook -i inventory/hosts setup.yml --tags=stop-group --extra-vars=group=jitsi; ansible-playbook -i inventory/hosts setup.yml --tags=install-service jitsi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This will ensure Jitsi is properly restarted after changes or issues.</p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><p>If you encounter issues, here are a few troubleshooting tips:</p><h3 id="no-moderator-assigned-to-calls" tabindex="-1">No Moderator Assigned to Calls <a class="header-anchor" href="#no-moderator-assigned-to-calls" aria-label="Permalink to &quot;No Moderator Assigned to Calls&quot;">​</a></h3><p>This is a common issue tracked on GitHub. You can check this known issue here: <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/issues/2589" target="_blank" rel="noreferrer">No moderator assigned to calls</a>.</p><p>As a potential fix, you may need to clean up the Jitsi folder:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -rf /matrix/jitsi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="sync-power-levels" tabindex="-1">Sync Power Levels <a class="header-anchor" href="#sync-power-levels" aria-label="Permalink to &quot;Sync Power Levels&quot;">​</a></h3><p>Ensure that the following variable is set to <code>false</code> if you&#39;re having issues with Matrix power level synchronization for Jitsi:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jitsi_prosody_auth_matrix_uvs_sync_power_levels: false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This prevents Jitsi from syncing moderation with Matrix power levels, which can sometimes cause unexpected behavior.</p><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><p>For more detailed documentation and community support, visit the official Matrix Docker Ansible Deploy <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy" target="_blank" rel="noreferrer">repository</a>.</p>`,29)])])}const b=s(n,[["render",o]]);export{u as __pageData,b as default};
